'use strict';
const options=(values,current)=>values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(label(v))}</option>`).join('');
const statusLabels={pending:'Invitation pending',accepted:'Connected',declined:'Invitation declined',closed:'Connection closed'};
async function getNames(ids){const unique=[...new Set(ids)].filter(Boolean);if(!unique.length)return {};return Object.fromEntries((await query(db.from('web_profiles').select('user_id,display_name').in('user_id',unique))).map(p=>[p.user_id,p.display_name]))}
function communityShell(tab){return pageTop('TREKSOR / COMMUNITY','Find your people.<br>Your own way.','Shared activities. Meaningful connections. A place to belong, with room to be yourself.',tab==='groups'?btn('Start a group ＋','create-group','','ghost'):'')+`<section class="community-body"><div class="wrap"><nav class="tabs" aria-label="Ways to connect"><a class="tab ${tab==='groups'?'active':''}" href="#/community">${icon('people')} Groups</a><a class="tab ${tab==='buddy'?'active':''}" href="#/community/one-to-one">${icon('buddy')} One-to-one <small>YOUR PACE</small></a><a class="tab ${tab==='mentors'?'active':''}" href="#/community/mentors">${icon('compass')} Mentors</a></nav><div id="community-results"><div class="loading">Finding your next step…</div></div></div></section>`}
function filterForm(tab){const f=state.filters;return `<form class="filters" id="filters"><label><span class="filter-label">${tab==='groups'?'FIND A GROUP':'SEARCH BY NAME'}</span><input name="q" value="${esc(f.q)}" maxlength="80" placeholder="${tab==='groups'?'An activity, an interest…':'A name…'}"></label><label><span class="filter-label">CITY</span><input name="city" value="${esc(f.city)}" maxlength="100" placeholder="Your city"></label><label><span class="filter-label">${tab==='mentors'?'PILLAR':'INTEREST'}</span><select name="category"><option value="">All</option>${options(tab==='mentors'?pillarData.map(p=>p.name):categories,f.category)}</select></label><button class="button ghost" type="submit">Search ↗</button></form>`}
async function renderCommunity(tab,version){const f=state.filters;let html='';if(tab!=='groups'&&!state.user){html=empty(tab==='buddy'?'One person. One simple plan.':'Guidance for your next step.','Sign in with your Treksor account to explore profiles and send invitations. Your email stays private.',btn('Sign in to Community ↗','login'),tab==='buddy'?'buddy':'compass')}
else if(tab==='groups'){let q=db.from('web_groups').select('*').order('created_at',{ascending:false}).limit(60);if(f.q)q=q.ilike('title',`%${f.q}%`);if(f.city)q=q.ilike('city',`%${f.city}%`);if(categories.includes(f.category))q=q.eq('category',f.category);const groups=await query(q);html=filterForm(tab)+`<div class="chips">${categories.map(c=>`<button class="chip ${f.category===c?'active':''}" data-action="category" data-id="${esc(c)}">${esc(label(c))}</button>`).join('')}</div><div class="result-top"><span>${groups.length} groups found</span><span><i class="status-dot"></i> Real connections, your pace</span></div>`+(groups.length?`<div class="card-grid">${groups.map(groupCard).join('')}</div>`:empty('Good stories start with a first plan.','No groups match this search yet. Start a walk, a coffee catch-up or an activity in your city.',`<div class="inline-actions">${btn('Create a group ＋','create-group')}${btn('Clear filters','clear-filters','','ghost')}</div>`,'people'))}
else if(tab==='buddy'){let q=db.from('web_profiles').select('*').eq('discoverable',true).neq('user_id',state.user.id).order('created_at',{ascending:false}).limit(60);if(f.q)q=q.ilike('display_name',`%${f.q}%`);if(f.city)q=q.ilike('city',`%${f.city}%`);if(categories.includes(f.category))q=q.contains('interests',[f.category]);const people=await query(q);html=`<div class="path-description"><div><h3>Two is a great start.</h3><p>A walk, a coffee, a shared interest. Start with a conversation and decide together what comes next. No crowd. No pressure.</p></div>${btn('My community profile ↗','profile','','ghost')}</div>`+filterForm(tab)+(people.length?`<div class="card-grid">${people.map(personCard).join('')}</div>`:empty('Your next connection has room to grow.','No profiles match yet. Set up your community profile and choose whether you want to receive invitations.',btn('Set up my profile ↗','profile'),'buddy'))}
else{let q=db.from('web_mentors').select('*,profile:web_profiles(display_name,city,bio)').eq('approved',true).order('created_at',{ascending:false}).limit(60);if(pillarData.some(p=>p.name===f.category))q=q.eq('specialty',f.category);const all=await query(q);const mentors=all.filter(m=>m.profile&&(!f.city||m.profile.city.toLowerCase().includes(f.city.toLowerCase()))&&(!f.q||m.profile.display_name.toLowerCase().includes(f.q.toLowerCase())));html=`<div class="path-description"><div><h3>A conversation can open a new direction.</h3><p>Explore a mentor's experience and introduce your goal. Agree on availability, format and any fees together.</p></div>${btn('Become a mentor ↗','apply-mentor','','ghost')}</div>`+filterForm(tab)+(mentors.length?`<div class="card-grid">${mentors.map(mentorCard).join('')}</div>`:empty('Our mentor network is growing.','Approved profiles will appear here. If you have experience to share, you can apply to become a mentor.',btn('Apply as a mentor ↗','apply-mentor'),'compass'))}
html+=`<div class="info-strip">${icon('shield')}<span>${tab==='mentors'?'Mentorship offers guidance, not medical or psychological care. Profile approval is not professional accreditation.':'You choose how to participate. Meet in public places, respect boundaries and report concerns when needed.'}</span></div>`;if(version===state.routeVersion)$('#community-results').innerHTML=html}
function groupCard(g){return `<article class="card"><div class="card-banner">${icon(g.category==='Hiking'||g.category==='Camping'?'mountain':g.category==='Café y charla'?'coffee':'people')}<span>${esc(label(g.category))}</span></div><div class="card-content"><div class="card-meta"><span>⌾ ${esc(g.city)}</span><span>${g.size_style==='small'?'Small-group preference':'Open group'}</span></div><h3>${esc(g.title)}</h3><p>${esc(g.description.slice(0,145))}${g.description.length>145?'…':''}</p><div class="card-foot"><span>A shared interest</span><a class="text-link" href="#/group/${g.id}">Explore group ↗</a></div></div></article>`}
function personCard(p){return `<article class="card"><div class="card-content"><div class="profile-card-top">${avatar(p.display_name)}<div><h3>${esc(p.display_name)}</h3><p>⌾ ${esc(p.city)}</p></div></div><p>${esc(p.bio||'Looking to share activities and meet people at my own pace.')}</p><div class="chips">${p.interests.map(i=>`<span class="chip">${esc(label(i))}</span>`).join('')}</div><div class="card-foot"><span>${esc(label(p.pace))} pace</span>${btn('Connect ↗','invite',p.user_id,'ghost')}</div></div></article>`}
function mentorCard(m){return `<article class="card"><div class="card-content"><div class="profile-card-top">${avatar(m.profile.display_name)}<div><h3>${esc(m.profile.display_name)}</h3><p>${esc(m.specialty)} · ${esc(label(m.format))}</p></div></div><h3 style="font-size:18px">${esc(m.headline)}</h3><p>${esc(m.description.slice(0,160))}</p><div class="card-foot"><span>${esc(m.profile.city||'Online')}</span>${btn('View profile ↗','mentor-detail',m.user_id,'ghost')}</div></div></article>`}
function profileDialog(){if(!needUser())return;const p=state.profile||{display_name:state.user.user_metadata?.name||state.user.user_metadata?.display_name||'',city:'',bio:'',interests:[],pace:'Tranquilo',discoverable:false};openDialog('Your profile. Your pace.',`<p class="lead">Choose what you share in Community. Your app progress remains private.</p><form id="profile-form" class="form-grid"><div class="form-row"><label>Public name<input name="display_name" value="${esc(p.display_name)}" required minlength="2" maxlength="60"></label><label>City<input name="city" value="${esc(p.city)}" required minlength="2" maxlength="100" placeholder="City only, no address"></label></div><label>About you<textarea name="bio" maxlength="600">${esc(p.bio)}</textarea></label><label>Your pace<select name="pace">${options(['Tranquilo','Intermedio','Activo'],p.pace)}</select></label><fieldset style="border:0;padding:0"><legend>Your interests</legend><div class="form-row">${categories.map(c=>`<label class="checkbox"><input type="checkbox" name="interests" value="${esc(c)}" ${p.interests.includes(c)?'checked':''}><span>${esc(label(c))}</span></label>`).join('')}</div></fieldset><label class="checkbox"><input type="checkbox" name="discoverable" ${p.discoverable?'checked':''}><span>Show my profile in One-to-one so members can invite me.</span></label><p class="helper">Your community name can be a nickname. Your city, bio, interests and pace are shared with your contacts, when you opt in to One-to-one, or when you become an approved mentor.</p><div class="form-error" role="alert"></div><button class="button" type="submit">Save community profile ↗</button></form>`,'COMMUNITY / PROFILE')}
function groupDialog(g=null){if(!needProfile())return;state.dialogContext={group:g};openDialog(g?'Shape your next meetup.':'A good plan starts with you.',`<form id="group-form" class="form-grid"><label>Group name<input name="title" required minlength="4" maxlength="90" value="${esc(g?.title||'')}" placeholder="Weekend walks in Brisbane"></label><div class="form-row"><label>Activity<select name="category">${options(categories,g?.category)}</select></label><label>City<input name="city" required minlength="2" maxlength="100" value="${esc(g?.city||state.profile.city)}"></label></div><label>What would you like to share?<textarea name="description" required minlength="10" maxlength="1200" placeholder="The idea, activity level and who this group is for…">${esc(g?.description||'')}</textarea></label><label>Group format<select name="size_style"><option value="small">We prefer small meetups</option><option value="open" ${g?.size_style==='open'?'selected':''}>All group sizes welcome</option></select></label><label>Next activity (optional)<input name="next_activity" maxlength="300" value="${esc(g?.next_activity||'')}"></label><p class="helper">Group descriptions are public. Small-group format is a preference, not an automatic participant limit. Share personal details only when appropriate.</p><div class="form-error" role="alert"></div><button class="button" type="submit">${g?'Save changes':'Create group'} ↗</button></form>`,'COMMUNITY / GROUPS')}
async function inviteDialog(id,kind='buddy'){if(!needProfile())return;if(id===state.user.id){toast('This is your own profile.');return}const p=await query(db.from('web_profiles').select('display_name').eq('user_id',id).single());const existing=await query(db.from('web_connections').select('id').eq('kind',kind).or(`and(from_user.eq.${state.user.id},to_user.eq.${id}),and(from_user.eq.${id},to_user.eq.${state.user.id})`).maybeSingle());if(existing){closeDialog();go('/connection/'+existing.id);return}state.dialogContext={id,kind};openDialog(kind==='mentor'?'Introduce your next goal.':'It starts with a hello.',`<p class="lead">Introduce yourself to <strong>${esc(p.display_name)}</strong>. A private conversation opens if your invitation is accepted.</p><form id="invite-form" class="form-grid"><label>${kind==='mentor'?'What would you like guidance with?':'What activity would you like to share?'}<textarea name="introduction" required minlength="10" maxlength="1000" placeholder="A little about you and what you have in mind…"></textarea></label><p class="helper">Keep phone numbers, addresses and sensitive information out of your introduction.</p><div class="form-error" role="alert"></div><button class="button" type="submit">Send invitation ↗</button></form>`,'COMMUNITY / '+(kind==='mentor'?'MENTORSHIP':'ONE-TO-ONE'))}
async function applyMentorDialog(){if(!needProfile())return;const m=await query(db.from('web_mentors').select('approved').eq('user_id',state.user.id).maybeSingle());if(m){openDialog(m.approved?'Your mentor profile is live.':'Your application is being reviewed.',`<div class="dialog-text"><p>${m.approved?'View your mentorship invitations in My space.':'Your profile will appear after Treksor reviews your experience and information.'}</p><a class="button" href="#/space" data-action="close">Go to My space ↗</a>${btn('Withdraw application / profile','withdraw-mentor','','ghost')}</div>`);return}openDialog('Share what you have learned.',`<p class="lead">Tell us about your experience. Your profile will be reviewed before publication.</p><form id="mentor-form" class="form-grid"><label>A short introduction<input name="headline" required minlength="5" maxlength="100"></label><div class="form-row"><label>Pillar<select name="specialty">${options(pillarData.map(p=>p.name))}</select></label><label>Format<select name="format">${options(['Online','Presencial','Ambos'])}</select></label></div><label>How can you help?<textarea name="description" required minlength="20" maxlength="1200"></textarea></label><label>Experience and public references<textarea name="experience" required minlength="10" maxlength="1200" placeholder="Relevant experience, training and public links. Do not include identity documents."></textarea></label><label class="checkbox"><input type="checkbox" required><span>This information is accurate and I understand my application will be reviewed.</span></label><div class="form-error" role="alert"></div><button class="button" type="submit">Submit application ↗</button></form>`,'COMMUNITY / MENTORS')}
async function mentorDetail(id){if(!needUser())return;const m=await query(db.from('web_mentors').select('*,profile:web_profiles(display_name,city)').eq('user_id',id).eq('approved',true).single());if(!m.profile)fail('This profile is unavailable.');openDialog(esc(m.profile.display_name),`<div class="dialog-text"><span class="tag">${esc(m.specialty)} · ${esc(label(m.format))} · ${esc(m.profile.city)}</span><h3>${esc(m.headline)}</h3><p>${esc(m.description)}</p><h3>Experience</h3><p>${esc(m.experience)}</p><div class="notice">Agree on availability, scope and any fees before arranging a session.</div>${btn('Contact this mentor ↗','mentor-invite',id)}${btn('Report profile','report-user',id,'ghost')}</div>`,'MENTOR PROFILE')}
function connectionRow(c,names,incoming=false){const other=c.from_user===state.user.id?c.to_user:c.from_user;return `<div class="list-row"><div class="row-content"><span class="tag">${c.kind==='mentor'?'Mentorship':'One-to-one'} · ${statusLabels[c.status]}</span><h3>${esc(names[other]||'Treksor member')}</h3><p>${esc(c.introduction.slice(0,125))}</p></div><div class="actions">${incoming?btn('Accept','accept',c.id)+btn('Decline','decline',c.id,'ghost'):''}<a class="button small ghost" href="#/connection/${c.id}">${c.status==='accepted'?'Chat':'View'} ↗</a></div></div>`}
async function renderDashboard(version){if(!state.user){main.innerHTML=signInPage();return}const [connections,members,owned,mentor,blocks]=await Promise.all([query(db.from('web_connections').select('*').order('created_at',{ascending:false}).limit(100)),query(db.from('web_group_members').select('group:web_groups(*)').eq('user_id',state.user.id)),query(db.from('web_groups').select('*').eq('owner_id',state.user.id)),query(db.from('web_mentors').select('*').eq('user_id',state.user.id).maybeSingle()),query(db.from('web_blocks').select('*').eq('blocker_id',state.user.id))]);if(version!==state.routeVersion)return;const names=await getNames(connections.flatMap(c=>[c.from_user,c.to_user]));const groups=[...new Map([...owned,...members.map(m=>m.group).filter(Boolean)].map(g=>[g.id,g])).values()];const incoming=connections.filter(c=>c.to_user===state.user.id&&c.status==='pending');const other=connections.filter(c=>!incoming.includes(c));const p=state.profile;const html=pageTop('MY SPACE',`Welcome, ${esc(accountName())}.`,'Your profile. Your progress. Your people.')+spaceTabs('space')+`<section class="dashboard"><div class="wrap dashboard-grid"><aside class="profile-panel">${avatar(accountName(),true,state.user.user_metadata?.avatar_url)}<h3>${esc(accountName())}</h3><p>${esc(p?.city||'Your journey, connected.')}</p><div class="spaced"><span class="tag">${p?.discoverable?'Visible in One-to-one':'Private community profile'}</span></div><a class="button small ghost" href="#/profile">App profile ↗</a><a class="text-link" href="#/progress">My progress ↗</a>${btn('Community preferences','profile','','ghost')}${btn(mentor?'My mentor application':'Become a mentor','apply-mentor','','ghost')}${state.admin?'<a class="text-link" href="#/admin">Manage community ↗</a>':''}<hr>${btn('Sign out','logout','','ghost')}</aside><div><section class="dash-section"><div class="dash-title"><h2>Your invitations</h2>${btn('Refresh ↻','refresh','','ghost')}</div>${incoming.length?incoming.map(c=>connectionRow(c,names,true)).join(''):'<div class="simple-empty">No new invitations yet. You choose which connections to accept.</div>'}</section><section class="dash-section"><div class="dash-title"><h2>Your connections</h2><a class="text-link" href="#/community/one-to-one">Explore ↗</a></div>${other.length?other.map(c=>connectionRow(c,names)).join(''):'<div class="simple-empty">A conversation can be a beginning. Explore One-to-one or find a mentor.</div>'}</section><section class="dash-section"><div class="dash-title"><h2>Your groups</h2>${btn('Create a group ＋','create-group','','ghost')}</div>${groups.length?groups.map(g=>`<div class="list-row"><div><span class="tag">${esc(label(g.category))} · ${g.owner_id===state.user.id?'You organise':'Member'}</span><h3>${esc(g.title)}</h3><p>${esc(g.city)}</p></div><a class="button small ghost" href="#/group/${g.id}">Open group ↗</a></div>`).join(''):'<div class="simple-empty">Find a group around something you enjoy, or start the first one.</div>'}</section>${blocks.length?`<section class="dash-section"><h2>Blocked contacts</h2>${blocks.map((b,i)=>`<div class="list-row"><p>Blocked contact ${i+1} · ${date(b.created_at)}</p>${btn('Unblock','unblock',b.blocked_id,'ghost')}</div>`).join('')}</section>`:''}</div></div></section>`;if(version===state.routeVersion)main.innerHTML=html}
async function renderGroup(id,version){const g=await query(db.from('web_groups').select('*').eq('id',id).maybeSingle());if(!g)fail('This group is no longer available.');const own=g.owner_id===state.user?.id;let member=null,posts=[];if(state.user){member=await query(db.from('web_group_members').select('user_id').eq('group_id',id).eq('user_id',state.user.id).maybeSingle());if(member||own)posts=await query(db.from('web_group_posts').select('*').eq('group_id',id).order('created_at',{ascending:false}).limit(60))}const joined=own||!!member;const names=state.user?await getNames(posts.map(p=>p.user_id)):{};if(version!==state.routeVersion)return;main.innerHTML=`<section class="section"><div class="wrap"><a class="back-link" href="#/community">← Back to groups</a><div class="detail-head"><div class="eyebrow spaced">COMMUNITY / ${esc(label(g.category))}</div><h1>${esc(g.title)}</h1><p>${esc(g.city)} · ${g.size_style==='small'?'Small-group preference':'Open group'}</p></div><div class="detail-grid"><div><div class="detail-panel"><h3>What brings us together</h3><p>${esc(g.description)}</p>${g.next_activity?`<h3 class="spaced">The next plan</h3><p>${esc(g.next_activity)}</p>`:''}</div><div class="detail-panel"><div class="dash-title"><h3>Group conversation</h3>${joined?btn('Refresh ↻','refresh','','ghost'):''}</div>${joined?`<div class="posts">${posts.length?posts.reverse().map(p=>`<article class="post${p.user_id===state.user.id?' mine':''}"><small>${esc(names[p.user_id]||'Group member')} · ${date(p.created_at)}</small><p>${esc(p.body)}</p></article>`).join(''):'<div class="simple-empty">Be the first to suggest a plan.</div>'}</div><form id="post-form" class="post-form" data-id="${id}"><label>Share an idea<textarea name="body" required minlength="1" maxlength="2000" placeholder="A plan, a question, a hello…"></textarea></label><button type="submit" class="button">Post ↗</button><div class="form-error" role="alert"></div></form>`:'<p>Join the group to read and take part in the conversation.</p>'}</div></div><aside><div class="detail-panel"><h3>${joined?'You belong here.':'A place to share.'}</h3><p>Discuss the activity level, location and what to bring before attending.</p>${own?btn('Edit group','edit-group',id,'ghost'):member?btn('Leave group','leave-group',id,'ghost'):btn('Join group ↗','join-group',id)}</div><div class="info-strip">${icon('shield')}<span>Choose a public place for first meetings. Do not post personal addresses.</span></div>${state.user?btn('Report group','report-group',id,'ghost'):''}${own?btn('Delete group','delete-group-confirm',id,'ghost'):''}</aside></div></div></section>`}
async function renderConnection(id,version){if(!state.user){main.innerHTML=signInPage();return}const c=await query(db.from('web_connections').select('*').eq('id',id).maybeSingle());if(!c)fail('This conversation is unavailable.');const other=c.from_user===state.user.id?c.to_user:c.from_user;const [names,messages,blocks]=await Promise.all([getNames([other]),query(db.from('web_messages').select('*').eq('connection_id',id).order('created_at',{ascending:false}).limit(100)),query(db.from('web_blocks').select('*').or(`and(blocker_id.eq.${state.user.id},blocked_id.eq.${other}),and(blocker_id.eq.${other},blocked_id.eq.${state.user.id})`))]);if(version!==state.routeVersion)return;const blocked=!!blocks.length,name=names[other]||'Treksor member';main.innerHTML=`<section class="section"><div class="wrap prose"><a class="back-link" href="#/space">← My space</a><div class="detail-head"><div class="eyebrow">${c.kind==='mentor'?'MENTORSHIP':'ONE-TO-ONE'} / ${statusLabels[c.status]}</div><h1>${esc(name)}</h1></div><div class="connection-summary"><span class="tag">The first hello</span><p>${esc(c.introduction)}</p>${c.status==='pending'&&c.to_user===state.user.id&&!blocked?`<div class="conversation-actions">${btn('Accept and chat','accept',id)}${btn('Decline','decline',id,'ghost')}</div>`:''}</div>${btn('Refresh conversation ↻','refresh','','ghost')}<div class="posts">${messages.reverse().map(m=>`<article class="post${m.sender_id===state.user.id?' mine':''}"><small>${m.sender_id===state.user.id?'You':esc(name)} · ${date(m.created_at)}</small><p>${esc(m.body)}</p></article>`).join('')}</div>${c.status==='accepted'&&!blocked?`<form id="message-form" class="post-form" data-id="${id}"><label>Your message<textarea name="body" required minlength="1" maxlength="2000" placeholder="Connect at your own pace…"></textarea></label><button class="button" type="submit">Send ↗</button><div class="form-error" role="alert"></div></form>`:`<div class="notice">${blocked?'This contact is blocked. New messages are disabled.':c.status==='pending'?'The conversation opens when the invitation is accepted.':c.status==='declined'?'This invitation was declined. Please respect their choice.':'This connection is closed. Your conversation history is still available.'}</div>`}<div class="conversation-actions spaced">${!blocked?btn('Block contact','block-confirm',other,'ghost'):''}${['accepted','pending'].includes(c.status)?btn('Close connection','close-connection-confirm',id,'ghost'):''}${btn('Report','report-user',other,'ghost')}</div></div></section>`}
function reportDialog(id,group=false){if(!needUser())return;state.dialogContext={id,group};openDialog('Help us care for this space.',`<p class="lead">Your report is visible to you and Treksor administrators.</p><form id="report-form" class="form-grid"><label>What happened?<textarea name="reason" required minlength="10" maxlength="1500"></textarea></label><div class="form-error" role="alert"></div><button class="button" type="submit">Send report ↗</button></form>`,'COMMUNITY / REPORT')}
function confirmDialog(title,text,action,id){openDialog(title,`<div class="dialog-text"><p>${text}</p><div class="inline-actions">${btn('Confirm',action,id,'danger')}${btn('Cancel','close','','ghost')}</div></div>`)}
async function renderAdmin(version){if(!state.admin)fail('This area is for Treksor administrators.');const [mentors,reports]=await Promise.all([query(db.from('web_mentors').select('*,profile:web_profiles(display_name,city)').eq('approved',false).order('created_at')),query(db.from('web_reports').select('*').eq('resolved',false).order('created_at'))]);const names=await getNames(reports.flatMap(r=>[r.reporter_id,r.target_user]));if(version!==state.routeVersion)return;main.innerHTML=pageTop('COMMUNITY / MANAGEMENT','Care for the community.','Review experience, references and reports before making a decision.')+`<div class="wrap dashboard"><section class="dash-section"><h2>Mentor applications</h2>${mentors.length?mentors.map(m=>`<article class="detail-panel"><span class="tag">${esc(m.specialty)} · ${esc(label(m.format))}</span><h3>${esc(m.profile?.display_name||'Member')} — ${esc(m.headline)}</h3><p>${esc(m.description)}</p><h3 class="spaced">Experience and references</h3><p>${esc(m.experience)}</p><div class="conversation-actions">${btn('Approve profile','approve-mentor',m.user_id)}${btn('Remove application','reject-mentor-confirm',m.user_id,'ghost')}</div></article>`).join(''):'<div class="simple-empty">No applications waiting for review.</div>'}</section><section class="dash-section"><h2>Open reports</h2>${reports.length?reports.map(r=>`<article class="detail-panel"><h3>Report from ${esc(names[r.reporter_id]||'Member')}</h3><p>${esc(r.reason)}</p>${r.target_user?`<p>Reported profile: ${esc(names[r.target_user]||r.target_user)}</p>`:''}${r.target_group?`<a class="text-link" href="#/group/${r.target_group}">Review group ↗</a>`:''}<div class="conversation-actions">${btn('Mark reviewed','resolve-report',r.id,'ghost')}${r.target_user?btn('Remove mentor profile','reject-mentor-confirm',r.target_user,'ghost'):''}${r.target_group?btn('Delete group','delete-group-confirm',r.target_group,'ghost'):''}</div></article>`).join(''):'<div class="simple-empty">No reports waiting for review.</div>'}</section></div>`}
